$(document).ready(function(){var a=$("#country"),e=$("#state"),n="",o="";a.change(c=>{a.val()!=""&&i()}),a.find(":selected").val()!=""&&i();function i(){n=a.val(),o=e.val(),e.empty(),e.append('<option disabled selected value="">-Seleccionar una opcion-</option>'),$.ajax({type:"get",url:location.origin+"/api/state/"+n,success:function(c){$.each(c,function(s,t){o==t.state_name?e.append('<option selected value="'+t.state_name+'">'+t.state_name+"</option>"):e.append('<option value="'+t.state_name+'">'+t.state_name+"</option>")})}})}});
